  FROM A7000900
 WHERE COD_CIA=1 AND NUM_SINI={ID:NUMBER.15:Required}',1,'Siniestro','Siniestro',0,NULL,'Siniestro','TRON',0,NULL,NULL,1,0,6329,TIMESTAMP'2024-06-21 00:00:00',NULL,NULL);
INSERT INTO ALIADOS.RESTENDPOINTS (ID,"PATH","SEQUENCE",VERB,SUMMARY,DESCRIPTION,STATEMENTTYPE,DATASOURCE,"STATEMENT",ONERECORD,"SOURCE",ALIAS,AUTHORIZATIONREQUIRED,ROLES,CONTROLLERNAME,APPNAME,TRACED,PRECONDITION,VALIDATIONS,RECORDSTATUS,COMPANYID,UPDATEUSERCODE,UPDATEDATE,PRECALL,POSTCALL) VALUES (302,'Siniestro/{id}',2,'GET','Expedientes',NULL,'SELECT',2,'SELECT NUM_EXP, TIP_EXP, TIP_EST_EXP, COD_SECTOR, COD_RAMO, MCA_EXP_RECOBRO, MCA_RECOBRO, TIP_EST_RECOBRO, NUM_EXP_AFEC, TIP_EXP_AFEC, TIP_EST_AFEC, MCA_JUICIO, TIP_EST_JUICIO, FEC_APER_EXP, FEC_TERM_EXP, FEC_MODI_EXP, FEC_REAP_EXP, FEC_ULT_LIQ, MCA_PROVISIONAL, FEC_AUTORIZACION, TIP_DOCUM, COD_DOCUM, NOMBRE, APELLIDOS, COD_MON, IMP_VAL_INICIAL, MCA_RVA_MANUAL, IMP_VAL, IMP_LIQ, IMP_PAG, IMP_VAL_NETO, IMP_LIQ_NETO, IMP_PAG_NETO, PCT_COA, IMP_RVA_3112, FEC_RVA_3112, COD_SUPERVISOR, COD_TRAMITADOR, MCA_CALCULA_RVA, COD_NIVEL1, COD_NIVEL2, COD_NIVEL3, TIP_APERTURA, FEC_DENU_EXP, FEC_AVISO_EXP, MCA_APER_NWT, COD_USR, FEC_ACTU
  FROM A7001000
 WHERE COD_CIA=1 AND NUM_SINI={ID:NUMBER.15:Required} ORDER BY NUM_EXP',0,'Siniestro','Expedientes',0,NULL,'Siniestro','TRON',0,'parameters.ContainsKey("include") && ( (string)parameters["include"]=="*" || ((string)parameters["include"]).ToLower().Contains("expedientes"))',NULL,1,0,6329,TIMESTAMP'2024-06-21 00:00:00',NULL,NULL);
INSERT INTO ALIADOS.RESTENDPOINTS (ID,"PATH","SEQUENCE",VERB,SUMMARY,DESCRIPTION,STATEMENTTYPE,DATASOURCE,"STATEMENT",ONERECORD,"SOURCE",ALIAS,AUTHORIZATIONREQUIRED,ROLES,CONTROLLERNAME,APPNAME,TRACED,PRECONDITION,VALIDATIONS,RECORDSTATUS,COMPANYID,UPDATEUSERCODE,UPDATEDATE,PRECALL,POSTCALL) VALUES (405,'ElectronicWarranty/Guarantee',1,'GET','Recupera una garantía electrónica por medio de número de garantía',NULL,'SELECT',1,'SELECT ID "ID", Institution_identifier "Institution_identifier", Supplier_identifier "Supplier_identifier", Guarantee_identifier "Guarantee_identifier", Guarantee_name "Guarantee_name", Institucion_notice_number "Institucion_notice_number", Notice_number "Notice_number", Cuenta_cliente "Cuenta_cliente", Guarantee_charge_person_name "Guarantee_charge_person_name", Guarantee_charge_person_email "Guarantee_charge_person_email", Guarantee_telephone_number "Guarantee_telephone_number", Guarantee_postal_code "Guarantee_postal_code", Guarantee_address_line "Guarantee_address_line", Guarantee_number "Guarantee_number", Guarantee_sequencenumber "Guarantee_sequencenumber", Guarantee_type_code "Guarantee_type_code", Guarantee_payment_code "Guarantee_payment_code", Guarantee_amount "Guarantee_amount", Moneda "Moneda", Issue_date "Issue_date", Valid_period_date "Valid_period_date", Tipo_de_modification "Tipo_de_modification", Guarantee_contents "Guarantee_contents", Confirmation "Confirmation", Msg_err "Msg_err", UpdateUserCode "UpdateUserCode", UpdateDate "UpdateDate", SUPPLIER_NAME "Supplier_name", EX_METODO "Ex_Metodo", EX_CODIGO_PROCESO "Ex_Codigo_Proceso", EX_FECHA_PROCESO "Ex_Fecha_Proceso", EX_AMOUNT "Ex_Amount", EX_CONTENTS "Ex_Contents", EX_CUENTA_CLIENTE "Ex_Cuenta_Cliente" FROM ElectronicWarranty P WHERE Guarantee_number={code:VARCHAR2.14:Required} AND P.Guarantee_sequencenumber = (SELECT max(Guarantee_sequencenumber) FROM ElectronicWarranty M WHERE M.Guarantee_number = P.Guarantee_number)',1,'ElectronicWarranty','Guarantee',0,NULL,'ElectronicWarranty','ElectronicWarranty',0,NULL,NULL,1,0,6329,TIMESTAMP'2024-05-13 00:00:00',NULL,NULL);
